import type { ReactNode } from 'react'
import { Navigate, Route, Routes, useLocation } from 'react-router-dom'

import { isIncomplete } from './data/model'
import { Home } from './pages/Home'
import { Members } from './pages/Members'
import { NotFound } from './pages/NotFound'
import { Settings } from './pages/Settings'
import { AppStateProvider, useAppState } from './state'

/** 初回設定が済んでいない人は、必須項目が埋まるまで初回設定へ誘導する */
const RequireSetup = ({ children }: { children: ReactNode }) => {
  const { me } = useAppState()
  const { search } = useLocation()
  if (me && isIncomplete(me)) return <Navigate to={`/settings${search}`} replace />
  return children
}

export const App = () => {
  const { search } = useLocation()
  const scenarioId = new URLSearchParams(search).get('state')
  return (
    <AppStateProvider scenarioId={scenarioId}>
      <Routes>
        <Route
          path="/"
          element={
            <RequireSetup>
              <Home />
            </RequireSetup>
          }
        />
        <Route
          path="/members"
          element={
            <RequireSetup>
              <Members />
            </RequireSetup>
          }
        />
        <Route path="/settings" element={<Settings />} />
        <Route path="*" element={<NotFound />} />
      </Routes>
    </AppStateProvider>
  )
}

import logoSvg from '../assets/gaji-labo-logo.svg?raw'

import './logo.css'

/** Gaji-Labo のロゴ（currentColor で塗られる SVG）。Header の上では白で表示する。 */
export const GajiLaboLogo = ({ tone = 'white' }: { tone?: 'white' | 'black' }) => (
  <span
    className="ct-logo"
    data-tone={tone}
    role="img"
    aria-label="Gaji-Labo（新しいタブで開きます）"
    // eslint-disable-next-line react/no-danger -- 固定のロゴ SVG（brief/gaji-labo-logo.svg）を埋め込むため
    dangerouslySetInnerHTML={{ __html: logoSvg.replace(/<metadata>[\s\S]*?<\/metadata>/, '') }}
  />
)

